  const sorted = [...s.ratings].sort((a, b) => b - a);
  let v = sorted.reduce((a, b, i) => a + b * (i < 4 ? 1.15 : 0.8), 0) / s.ids.length;
  const has = (r) => s.roles.some((x) => x.has(r));
