  const starters2 = new Set(L.slots.map((x) => x.monId));
  const listed = L.slots[i].backups.map((id) => s.mons[id]).filter((m) => m && !starters2.has(m.id) && !out(m) && fit(m, slotRoles(i)));
  if (listed.length >= 2) return listed.slice(0, 2);
